import type { CoachSource } from '../constants';
import type { ISODateTime } from './common';

export interface CoachThreadDTO {
  id: string;
  title: string;
  createdAt: ISODateTime;
  updatedAt: ISODateTime;
  messageCount: number;
}

export interface CoachMessageDTO {
  id: string;
  threadId: string;
  role: 'user' | 'assistant';
  content: string;
  /** 'llm' = generated by the configured model; 'builtin' = deterministic offline coach. */
  source: CoachSource | null;
  status: 'ok' | 'error' | 'refused';
  createdAt: ISODateTime;
}

export interface CoachStatusDTO {
  llmConfigured: boolean;
  model: string | null;
  dailyLimit: number;
  usedToday: number;
  remainingToday: number;
}

export interface SendCoachMessageResponse {
  userMessage: CoachMessageDTO;
  reply: CoachMessageDTO;
  status: CoachStatusDTO;
}
